// Stages desktop/shared/ (generated by scripts/stage.mjs, gitignored) when it is missing, so suites that import the app's learning code can be loaded; guarded by test/harness/ensure-staged.test.mjs.
import {execFileSync} from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

// desktop: the app's folder. exec: how the stage script is run (a test passes a stub). -> true when it had to stage.
export function ensureStaged(desktop, exec = execFileSync) {
  if (fs.existsSync(path.join(desktop, 'shared', 'alias-schema.js'))) return false;
  exec(process.execPath, [path.join(desktop, 'scripts', 'stage.mjs'), '--files-only'], {cwd: desktop, stdio: 'ignore'});
  return true;
}
